create policy "print assets owner update" on storage.objects for update to authenticated using (bucket_id = 'print-assets' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'print-assets' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "print assets owner delete" on storage.objects for delete to authenticated using (bucket_id = 'print-assets' and (storage.foldername(name))[1] = auth.uid()::text);